373	    // ─── Sv39 页表管理器 ───
374	
375	    /// Sv39 页表管理器
376	    #[repr(transparent)]
377	    pub struct Sv39Manager(NonNull<Pte<Sv39>>);
378	
379	    impl Sv39Manager {
380	        const OWNED: VmFlags<Sv39> = unsafe { VmFlags::from_raw(1 << 8) };
381	        #[inline]
382	        fn page_alloc<T>(count: usize) -> *mut T {
383	            unsafe {
384	                alloc_zeroed(Layout::from_size_align_unchecked(
385	                    count << Sv39::PAGE_BITS,
386	                    1 << Sv39::PAGE_BITS,
387	                ))
388	            }
389	            .cast()
390	        }
391	    }
392	
393	    impl PageManager<Sv39> for Sv39Manager {
394	        #[inline]
395	        fn new_root() -> Self { Self(NonNull::new(Self::page_alloc(1)).unwrap()) }
396	        #[inline]
397	        fn root_ppn(&self) -> PPN<Sv39> { PPN::new(self.0.as_ptr() as usize >> Sv39::PAGE_BITS) }
398	        #[inline]
399	        fn root_ptr(&self) -> NonNull<Pte<Sv39>> { self.0 }
400	        #[inline]
401	        fn p_to_v<T>(&self, ppn: PPN<Sv39>) -> NonNull<T> {
402	            unsafe { NonNull::new_unchecked(VPN::<Sv39>::new(ppn.val()).base().as_mut_ptr()) }
403	        }
404	        #[inline]
405	        fn v_to_p<T>(&self, ptr: NonNull<T>) -> PPN<Sv39> {
406	            PPN::new(VAddr::<Sv39>::new(ptr.as_ptr() as _).floor().val())
407	        }
408	        #[inline]
409	        fn check_owned(&self, pte: Pte<Sv39>) -> bool { pte.flags().contains(Self::OWNED) }
410	        #[inline]
411	        fn allocate(&mut self, len: usize, flags: &mut VmFlags<Sv39>) -> NonNull<u8> {
412	            *flags |= Self::OWNED;
