595	    impl Clock for SyscallContext {
596	        #[inline]
597	        fn clock_gettime(&self, _caller: Caller, clock_id: ClockId, tp: usize) -> isize {
598	            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
599	            match clock_id {
600	                ClockId::CLOCK_MONOTONIC => {
601	                    if let Some(mut ptr) = PROCESSOR.get_mut().get_current_proc().unwrap()
602	                        .address_space.translate(VAddr::new(tp), WRITABLE)
603	                    {
604	                        let time = riscv::register::time::read() * 10000 / 125;
605	                        *unsafe { ptr.as_mut() } = TimeSpec {
606	                            tv_sec: time / 1_000_000_000,
607	                            tv_nsec: time % 1_000_000_000,
608	                        };
609	                        0
610	                    } else { log::error!("ptr not readable"); -1 }
611	                }
612	                _ => -1,
613	            }
614	        }
615	    }
