50	/// 同一进程的多个线程共享地址空间。
51	pub struct Thread {
52	    /// 线程 ID（不可变）
53	    pub tid: ThreadId,
54	    /// 执行上下文（包含 LocalContext + satp）
55	    pub context: ForeignContext,
56	}
57	
58	impl Thread {
59	    /// 创建新线程
60	    pub fn new(satp: usize, context: LocalContext) -> Self {
61	        Self {
62	            tid: ThreadId::new(),
63	            context: ForeignContext { context, satp },
64	        }
65	    }
66	}
67	
68	/// 进程（资源容器）
69	///
70	/// 管理地址空间、文件描述符、同步原语、信号等共享资源。
71	/// 一个进程可以包含多个线程。
72	pub struct Process {
73	    /// 进程 ID
74	    pub pid: ProcId,
75	    /// 地址空间（所有线程共享）
76	    pub address_space: AddressSpace<Sv39, Sv39Manager>,
77	    /// 文件描述符表（所有线程共享）
78	    pub fd_table: Vec<Option<Mutex<Fd>>>,
79	    /// 信号处理器
80	    pub signal: Box<dyn Signal>,
81	    /// 信号量列表（**本章新增**，所有线程共享）
82	    pub semaphore_list: Vec<Option<Arc<Semaphore>>>,
83	    /// 互斥锁列表（**本章新增**，所有线程共享）
84	    pub mutex_list: Vec<Option<Arc<dyn MutexTrait>>>,
85	    /// 条件变量列表（**本章新增**，所有线程共享）
86	    pub condvar_list: Vec<Option<Arc<Condvar>>>,
87	    /// 是否开启死锁检测
88	    pub is_deadlock_detect_enabled: bool,
89	    /// 线程已分配的 mutex
90	    pub mutex_allocations: alloc::collections::BTreeMap<usize, Vec<usize>>,
91	    /// 线程已分配的 semaphore
92	    pub sem_allocations: alloc::collections::BTreeMap<usize, Vec<usize>>,
93	    /// 线程正在请求（等待）的 mutex
94	    pub mutex_requests: alloc::collections::BTreeMap<usize, usize>,
95	    /// 线程正在请求（等待）的 semaphore
96	    pub sem_requests: alloc::collections::BTreeMap<usize, usize>,
97	}
98	
99	impl Process {
100	    /// exec：替换当前进程的地址空间和主线程上下文
101	    ///
102	    /// 注意：只支持单线程进程执行 exec
103	    pub fn exec(&mut self, elf: ElfFile) {
104	        let (proc, thread) = Process::from_elf(elf).unwrap();
105	        self.address_space = proc.address_space;
106	        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
107	        unsafe {
108	            let pthreads = (*processor).get_thread(self.pid).unwrap();
109	            (*processor).get_task(pthreads[0]).unwrap().context = thread.context;
110	        }
111	    }
112	
113	    /// fork：创建子进程（复制地址空间和主线程上下文）
114	    ///
115	    /// 子进程继承父进程的地址空间（深拷贝）、文件描述符和信号配置。
116	    /// 同步原语列表不继承（子进程创建空的列表）。
117	    pub fn fork(&mut self) -> Option<(Self, Thread)> {
118	        let pid = ProcId::new();
119	        // 深拷贝地址空间
120	        let parent_addr_space = &self.address_space;
121	        let mut address_space: AddressSpace<Sv39, Sv39Manager> = AddressSpace::new();
122	        parent_addr_space.cloneself(&mut address_space);
123	        map_portal(&address_space);
124	        // 复制主线程上下文
125	        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
126	        let pthreads = unsafe { (*processor).get_thread(self.pid).unwrap() };
127	        let context = unsafe {
128	            (*processor).get_task(pthreads[0]).unwrap().context.context.clone()
129	        };
130	        let satp = (8 << 60) | address_space.root_ppn().val();
131	        let thread = Thread::new(satp, context);
132	        // 复制文件描述符表
133	        let new_fd_table: Vec<Option<Mutex<Fd>>> = self.fd_table
134	            .iter()
135	            .map(|fd| fd.as_ref().map(|f| Mutex::new(f.lock().clone())))
136	            .collect();
137	        Some((
138	            Self {
139	                pid,
140	                address_space,
141	                fd_table: new_fd_table,
142	                signal: self.signal.from_fork(),
143	                // 子进程的同步原语列表初始为空
144	                semaphore_list: Vec::new(),
145	                mutex_list: Vec::new(),
146	                condvar_list: Vec::new(),
147	                is_deadlock_detect_enabled: false,
148	                mutex_allocations: alloc::collections::BTreeMap::new(),
149	                sem_allocations: alloc::collections::BTreeMap::new(),
150	                mutex_requests: alloc::collections::BTreeMap::new(),
151	                sem_requests: alloc::collections::BTreeMap::new(),
152	            },
153	            thread,
154	        ))
155	    }
156	
157	    /// 从 ELF 文件创建进程和主线程
158	    ///
159	    /// 解析 ELF 段，建立地址空间，分配用户栈，创建初始上下文。
160	    pub fn from_elf(elf: ElfFile) -> Option<(Self, Thread)> {
161	        let entry = match elf.header.pt2 {
162	            HeaderPt2::Header64(pt2)
163	                if pt2.type_.as_type() == header::Type::Executable
164	                    && pt2.machine.as_machine() == Machine::RISC_V =>
165	            { pt2.entry_point as usize }
166	            _ => None?,
167	        };
168	
169	        const PAGE_SIZE: usize = 1 << Sv39::PAGE_BITS;
170	        const PAGE_MASK: usize = PAGE_SIZE - 1;
171	
172	        let mut address_space = AddressSpace::new();
173	        for program in elf.program_iter() {
174	            if !matches!(program.get_type(), Ok(program::Type::Load)) { continue; }
175	            let off_file = program.offset() as usize;
176	            let len_file = program.file_size() as usize;
177	            let off_mem = program.virtual_addr() as usize;
178	            let end_mem = off_mem + program.mem_size() as usize;
179	            assert_eq!(off_file & PAGE_MASK, off_mem & PAGE_MASK);
180	            let mut flags: [u8; 5] = *b"U___V";
181	            if program.flags().is_execute() { flags[1] = b'X'; }
182	            if program.flags().is_write() { flags[2] = b'W'; }
183	            if program.flags().is_read() { flags[3] = b'R'; }
184	            address_space.map(
185	                VAddr::new(off_mem).floor()..VAddr::new(end_mem).ceil(),
186	                &elf.input[off_file..][..len_file],
187	                off_mem & PAGE_MASK,
188	                parse_flags(unsafe { core::str::from_utf8_unchecked(&flags) }).unwrap(),
189	            );
190	        }
191	        // 分配 2 页用户栈
192	        let stack = unsafe {
193	            alloc_zeroed(Layout::from_size_align_unchecked(
194	                2 << Sv39::PAGE_BITS, 1 << Sv39::PAGE_BITS,
195	            ))
196	        };
197	        address_space.map_extern(
198	            VPN::new((1 << 26) - 2)..VPN::new(1 << 26),
199	            PPN::new(stack as usize >> Sv39::PAGE_BITS),
200	            build_flags("U_WRV"),
201	        );
202	        map_portal(&address_space);
203	        let satp = (8 << 60) | address_space.root_ppn().val();
204	        let mut context = LocalContext::user(entry);
205	        *context.sp_mut() = 1 << 38;
206	        let thread = Thread::new(satp, context);
207	
208	        Some((
209	            Self {
210	                pid: ProcId::new(),
211	                address_space,
212	                fd_table: vec![
213	                    // stdin
214	                    Some(Mutex::new(Fd::Empty { read: true, write: false })),
215	                    // stdout
216	                    Some(Mutex::new(Fd::Empty { read: false, write: true })),
217	                    // stderr
218	                    Some(Mutex::new(Fd::Empty { read: false, write: true })),
219	                ],
220	                signal: Box::new(SignalImpl::new()),
221	                semaphore_list: Vec::new(),
222	                mutex_list: Vec::new(),
223	                condvar_list: Vec::new(),
224	                is_deadlock_detect_enabled: false,
225	                mutex_allocations: alloc::collections::BTreeMap::new(),
226	                sem_allocations: alloc::collections::BTreeMap::new(),
227	                mutex_requests: alloc::collections::BTreeMap::new(),
228	                sem_requests: alloc::collections::BTreeMap::new(),
229	            },
230	            thread,
231	        ))
232	    }
233	}
