1	//! # 第一章：应用程序与基本执行环境
2	//!
3	//! 本章实现了一个最简单的 RISC-V S 态裸机程序，展示操作系统的最小执行环境。
4	//!
5	//! ## 关键概念
6	//!
7	//! - `#![no_std]`：不使用 Rust 标准库，改用不依赖操作系统的核心库 `core`
8	//! - `#![no_main]`：不使用标准的 `main` 入口，自定义裸函数 `_start` 作为入口
9	//! - 裸函数（naked function）：不生成函数序言/尾声，可在无栈环境下执行
10	//! - SBI（Supervisor Binary Interface）：S 态软件向 M 态固件请求服务的标准接口
11	//!
12	//! 教程阅读建议：
13	//!
14	//! - 先看 `_start`：理解无运行时情况下的最小启动流程；
15	//! - 再看 `rust_main`：理解最小 I/O 路径（SBI 输出 + 关机）；
16	//! - 最后看 `panic_handler`：理解 no_std 程序的异常收口方式。
17	
18	// 不使用标准库，因为裸机环境没有操作系统提供系统调用支持
19	#![no_std]
20	// 不使用标准入口，因为裸机环境没有 C runtime 进行初始化
21	#![no_main]
22	// RISC-V64 架构下启用严格警告和文档检查
23	#![cfg_attr(target_arch = "riscv64", deny(warnings, missing_docs))]
24	// 非 RISC-V64 架构允许死代码（用于 cargo publish --dry-run 在主机上通过编译）
25	#![cfg_attr(not(target_arch = "riscv64"), allow(dead_code))]
26	
27	extern crate alloc;
28	
29	// 引入 SBI 调用库，提供 console_putchar（输出字符）和 shutdown（关机）功能
30	// 启用 nobios 特性后，tg_sbi 内建了 M-mode 启动代码，无需外部 SBI 固件
31	use tg_sbi::{console_putchar, shutdown};
32	
33	fn print_str(s: &str) {
34	    for b in s.bytes() {
35	        console_putchar(b);
36	    }
37	}
38	
39	/// S 态程序入口点。
40	///
41	/// 这是一个裸函数（naked function），放置在 `.text.entry` 段，
42	/// 链接脚本将其安排在地址 `0x80200000`。
43	///
44	/// 裸函数不生成函数序言和尾声，因此可以在没有栈的情况下执行。
45	/// 它完成两件事：
46	/// 1. 设置栈指针 `sp`，指向栈顶（栈从高地址向低地址增长）
47	/// 2. 跳转到 Rust 主函数 `rust_main`
48	#[cfg(target_arch = "riscv64")]
49	#[unsafe(naked)]
50	#[unsafe(no_mangle)]
51	#[unsafe(link_section = ".text.entry")]
52	unsafe extern "C" fn _start() -> ! {
53	    // 栈大小：4 KiB
54	    const STACK_SIZE: usize = 4096;
55	
56	    // 在 .bss.uninit 段中分配栈空间
57	    #[unsafe(link_section = ".bss.uninit")]
58	    static mut STACK: [u8; STACK_SIZE] = [0u8; STACK_SIZE];
59	
60	    core::arch::naked_asm!(
61	        "la sp, {stack} + {stack_size}", // 将 sp 设置为栈顶地址
62	        "j  {main}",                     // 跳转到 rust_main
63	        stack_size = const STACK_SIZE,
64	        stack      =   sym STACK,
65	        main       =   sym rust_main,
66	    )
67	}
68	
69	use core::ptr::NonNull;
70	use virtio_drivers::device::gpu::VirtIOGpu;
71	use virtio_drivers::transport::mmio::{MmioTransport, VirtIOHeader};
72	use virtio_drivers::transport::{DeviceType, Transport};
73	
74	use buddy_system_allocator::LockedHeap;
75	#[global_allocator]
76	static HEAP_ALLOCATOR: LockedHeap<32> = LockedHeap::empty();
77	static mut HEAP_SPACE: [u8; 0x400000] = [0; 0x400000];
78	
79	mod tangram;
80	mod gpu;
81	use gpu::VirtioHal;
82	
83	/// S 态内核主函数
84	///
85	/// 本函数不仅建立了操作系统的最小执行环境，还通过初始化并驱动 VirtIO GPU 设备，
86	/// 直观展示了裸机操作系统如何直接与硬件交互并进行数据处理。
87	/// 核心考察点与机制展示包含：
88	/// 1. 动态内存管理：通过伙伴系统（Buddy System）分配大块内存（内核堆），满足 VirtIO 复杂协议要求。
89	/// 2. 外设探测（MMIO Probing）：通过扫描预先约定的物理连续地址段寻找特征魔数以探测接入外围设备，并在内存总线上完成设备挂载。
90	/// 3. 帧缓冲（Framebuffer）抽象与 DMA 控制机制：申请建立显示设备的连续物理驱动内存窗口，绕过直接汇编进行画面到像素的渲染，并借助 `flush` 同步绘制。
91	/// 4. 生命周期抑制防收回与挂机策略（WFI）：通过显式泄漏 `core::mem::forget` 绕开 Rust 的清理策略以防止显存黑屏；基于汇编陷入低耗能态（Wait For Interrupt）。
92	extern "C" fn rust_main() -> ! {
93	    // 1. 初始化内核堆（全局内存分配器）
94	    // 大量外部硬件结构（如 VirtIO 控制队列）由于数量不可静态推测，需在运行时通过堆内存获取载体。
95	    unsafe {
96	        HEAP_ALLOCATOR.lock().init(
97	            core::ptr::addr_of_mut!(HEAP_SPACE).cast::<u8>() as usize,
98	            0x400000,
99	        );
100	    }
101	
102	    print_str("[OS] Starting Kernel and VirtIO probing...\n");
103	    let mut gpu_dev = None;
104	    
105	    // 2. 硬件设备探测（通过遍历 MMIO 区域空间实现挂载）
106	    // VirtIO 通过特定的物理地址区间（0x1000_1000 始，每跨度 0x1000 即为一个设备条目）将本身状态暴露至系统主存。
107	    for addr in (0x1000_1000..=0x1000_8000).step_by(0x1000) {
108	        // 读取特征识别码（魔数 `"virt"`），拦截所有真实接入且支持协议的总线响应
109	        if unsafe { core::ptr::read_volatile(addr as *const u32) } != 0x74726976 {
110	            continue;
111	        }
112	
113	        let header = NonNull::new(addr as *mut VirtIOHeader).unwrap();
114	        // 尝试封装基于底层传输层协议的对象
115	        if let Ok(transport) = unsafe { MmioTransport::new(header) } {
116	            // 校验到外设设备类型为 GPU 图形输出组件
117	            if transport.device_type() == DeviceType::GPU {
118	                print_str("[OS] VirtIO GPU discovered.\n");
119	                // 将基于平台定制的 DMA 和地址转换接口（VirtioHal）注入驱动并构建高级操控句柄
120	                match VirtIOGpu::<VirtioHal, MmioTransport>::new(transport) {
121	                    Ok(g) => {
122	                        gpu_dev = Some(g);
123	                        print_str("[OS] GPU initialized.\n");
124	                    }
125	                    Err(_e) => {
126	                        print_str("[OS] GPU Init Failed.\n");
127	                    }
128	                }
129	                break;
130	            }
131	        }
132	    }
133	
134	    // 3. 画面挂载与核心图层建立
135	    if let Some(mut gpu) = gpu_dev {
136	        print_str("[OS] Setting up Framebuffer...\n");
137	        let (width, _height) = match gpu.resolution() {
138	            Ok(res) => res,
139	            Err(_) => {
140	                print_str("[OS] Resolution query failed.\n");
141	                (0, 0)
142	            }
143	        };
144	        
145	        // 分配请求实际用于储存逐个像素颜色点、与物理显示接口等高同宽的显存区域（Framebuffer）
146	        let fb = match gpu.setup_framebuffer() {
147	            Ok(fb) => fb,
148	            Err(_) => {
149	                print_str("[OS] Framebuffer attach failed.\n");
150	                &mut []
151	            }
152	        };
153	        
154	        print_str("[OS] Drawing Tangram Geometry Array...\n");
155	        // 背景设定纯白 (通过直接写全等 255 实现 RGBA 位满像素投递)
156	        fb.fill(255);
157	
158	        // 调用算法引擎处理图形转换空间坐标并直接写入上一步拿到的像素内存中
159	        for poly in tangram::TANGRAM_O.iter() {
160	            tangram::fill_polygon(&poly.vertices, poly.color, fb, width);
161	        }
162	        for poly in tangram::TANGRAM_S.iter() {
163	            tangram::fill_polygon(&poly.vertices, poly.color, fb, width);
164	        }
165	
166	        print_str("[OS] Flushing pixels to hardware...\n");
167	        // 指针推刷，强迫图形设备直接在显现矩阵中对缓存变化重新进行取样和光栅应用
168	        let _ = gpu.flush();
169	        
170	        // 关键规避技术：抑制 RAII 释放
