149	// 扫描线算法填充多边形
150	pub fn fill_polygon(vertices: &[Point], color: [u8; 4], fb: &mut [u8], width: u32) {
151	    let min_y = vertices.iter().map(|v| v.y).min().unwrap_or(0).max(0);
152	    let max_y = vertices.iter().map(|v| v.y).max().unwrap_or(0);
153	    let min_x = vertices.iter().map(|v| v.x).min().unwrap_or(0).max(0);
154	    let max_x = vertices.iter().map(|v| v.x).max().unwrap_or(0);
155	
156	    for y in min_y..=max_y {
157	        for x in min_x..=max_x {
158	            let mut inside = false;
159	            let mut j = vertices.len() - 1;
160	            for i in 0..vertices.len() {
161	                let pi = &vertices[i];
162	                let pj = &vertices[j];
163	
164	                if (pi.y > y) != (pj.y > y) {
165	                    let intersect_x = pi.x + (pj.x - pi.x) * (y - pi.y) / (pj.y - pi.y);
166	                    if x < intersect_x {
167	                        inside = !inside;
168	                    }
169	                }
170	                j = i;
171	            }
172	
173	            if inside {
174	                let idx = ((y as usize) * (width as usize) + (x as usize)) * 4;
175	                if idx + 3 < fb.len() {
176	                    fb[idx] = color[0];
177	                    fb[idx + 1] = color[1];
178	                    fb[idx + 2] = color[2];
179	                    fb[idx + 3] = color[3];
180	                }
181	            }
182	        }
183	    }
184	}
